                        圣_guicai: {
                            audio: 'ext:混沌界/audio:2',
                            trigger: {
                                global: 'judge',
                            },
                            content() {
                                'step 0';
                                player.line(trigger.player);
                                ('step 1');
                                if (trigger.player != player && trigger.player.countCards('he')) {
                                    trigger.player.chooseCard('【鬼才】:请选择一张牌交给' + get.translation(player), 'he', true);
                                } else {
                                    event.goto(3);
                                }
                                ('step 2');
                                player.gain(result.cards[0], trigger.player, 'giveAuto');
                                ('step 3');
                                if (player.countCards('he')) {
                                    player.chooseCard('he', true, '【鬼才】:请将一张牌置于牌堆顶').ai = function (card) {
                                        return -get.value(card);
                                    };
                                } else {
                                    event.goto(5);
                                }
                                ('step 4');
                                if (result.cards?.length) {
                                    event.card = result.cards[0];
                                    player.lose(result.cards, ui.cardPile, 'insert');
                                    game.log(player, '将', event.card, '置于牌堆顶');
                                    game.broadcastAll(function (player) {
                                        var cardx = ui.create.card();
                                        cardx.classList.add('infohidden');
                                        cardx.classList.add('infoflip');
                                        player.$throw(cardx, 1000, 'nobroadcast');
                                    }, player);
                                }
                                ('step 5');
                                if (player.getDamagedHp() > 2) {
                                    var num = player.getDamagedHp();
                                } else {
                                    var num = 2;
                                }
                                event.cards = get.cards(num);
                                game.cardsGotoOrdering(event.cards);
                                ('step 6');
                                player.chooseCardButton(event.cards, '【鬼才】:请选择一张牌作为最终判定结果并获得其余牌', true).ai = function (button) {
                                    if (get.attitude(player, trigger.player) > 0) {
                                        return 1 + trigger.judge(button.link);
                                    }
                                    if (get.attitude(player, trigger.player) < 0) {
                                        return 1 - trigger.judge(button.link);
                                    }
                                    return 0;
                                };
                                ('step 7');
                                if (result.links?.length) {
                                    var card = result.links[0];
                                    event.cards.remove(card);
                                    var judgestr = get.translation(trigger.player) + `的${trigger.judgestr}判定`;
                                    event.videoId = lib.status.videoId++;
                                    event.dialog = ui.create.dialog(judgestr);
                                    event.dialog.classList.add('center');
                                    event.dialog.videoId = event.videoId;
                                    game.addVideo('judge1', player, [get.cardInfo(card), judgestr, event.videoId]);
                                    if (Array.isArray(event.cards)) for (var i of event.cards) i.discard();
                                    // var node=card.copy('thrown','center',ui.arena).addTempClass('start');
                                    var node;
                                    if (game.chess) {
                                        node = card.copy('thrown', 'center', ui.arena).addTempClass('start');
                                    } else {
                                        node = player.$throwordered(card.copy(), true);
                                    }
                                    node.classList.add('thrownhighlight');
                                    ui.arena.classList.add('thrownhighlight');
                                    if (card) {
                                        trigger.cancel();
                                        trigger.result = {
                                            card: card,
                                            judge: trigger.judge(card),
                                            node: node,
                                            number: card.number,
                                            suit: card.suit,
                                            color: get.color(card),
                                        };
                                        if (trigger.result.judge > 0) {
                                            trigger.result.bool = true;
                                            trigger.player.popup('洗具');
                                        }
                                        if (trigger.result.judge < 0) {
                                            trigger.result.bool = false;
                                            trigger.player.popup('杯具');
                                        }
                                        game.log(trigger.player, '的判定结果为', card);
                                        trigger.direct = true;
                                        trigger.position.appendChild(card);
                                    } else {
                                        event.finish();
                                    }
                                }
                                ('step 8');
                                ui.arena.classList.remove('thrownhighlight');
                                event.dialog.close();
                                game.addVideo('judge2', null, event.videoId);
                                ui.clear();
                                var card = trigger.result.card;
                                trigger.position.appendChild(card);
                                trigger.result.node.delete();
                                ('step 9');
                                if (result.bool) {
                                    player.gain(event.cards, 'gain2');
                                }
                            },
                        },
